"Slash through it to send it back. Do it right as your dash starts for a PERFECT PARRY.": "اضربها لتعيدها. افعلها لحظة بدء اندفاعك لتحصل على صدّ مثالي.",
"SHIELDED ENEMY": "عدو بدرع",
"The green arc blocks hits from the front. Hit it from behind, bounce off a rail first, or perfect-parry.": "القوس الأخضر يصد الضربات من الأمام. اضربه من الخلف، أو ارتد عن السياج أولاً، أو نفّذ صدّاً مثالياً.",
"The orange laser shows exactly where it will shoot. Step off the line or parry the shot.": "الليزر البرتقالي يُظهر بالضبط أين سيطلق. ابتعد عن الخط أو اصدّ الطلقة.",
"It blinks, then explodes. Slash it fast or get out of the ring.": "يومض ثم ينفجر. اضربه بسرعة أو اخرج من الحلقة.",
"It fades out and blinks next to you. Watch for the shimmer, then strike.": "يتلاشى ويظهر فجأة بجانبك. راقب الوميض، ثم اضرب.",
"Blue tethers give its friends a shield bubble. Cut the warden first.": "الروابط الزرقاء تمنح رفاقه فقاعة درع. اقطع الحارس أولاً.",
"ELITE ENEMY": "عدو نخبة",
"Gold ring: tougher and richer. Its tag is its trick: SWIFT is fast, VOLATILE explodes when it dies, SPLIT leaves two minis, AEGIS re-shields itself.": "الحلقة الذهبية: أقوى وأغنى. وسمه هو حيلته: السريع سريع، المتفجر ينفجر عند موته، المنقسم يترك صغيرين، الدرع يعيد درعه.",
"WEAKPOINT": "نقطة الضعف",
"Slash the gold arc to stagger the boss. While it is staggered, tap the boss fast for finishing slashes.": "اضرب القوس الذهبي لتترنح الزعيم. أثناء ترنحه، انقر على الزعيم بسرعة لضربات الإجهاز.",
"DATA TERMINAL": "محطة بيانات",
"Stand still inside the ring until it fills. Getting hit slows the upload.": "قف ثابتاً داخل الحلقة حتى تمتلئ. الإصابة تبطئ الرفع.",
"THE UPLINK": "جهاز الإرسال",
"Enemies that reach the uplink damage it. Bombers go for it first.": "الأعداء الذين يصلون إلى جهاز الإرسال يتلفونه. المفجّرون يستهدفونه أولاً.",
"EXPRESS TRAIN": "القطار السريع",
"Red stripes mean a train is coming down that track. Get off it, or lure enemies onto it.": "الخطوط الحمراء تعني أن قطاراً قادم على تلك السكة. ابتعد عنها أو استدرج الأعداء إليها.",
"OVERDRIVE READY": "الأوفردرايف جاهز",
"Tap OVERDRIVE: a few seconds of invincibility, endless dashes and double damage.": "اضغط أوفردرايف: بضع ثوانٍ من الحصانة واندفاعات بلا حدود وضرر مضاعف.",
"BLADE HEAT": "سخونة النصل",
