"This link is view-only: you can see the board, but your scores stay on this device. Ask the owner to invite you by email to join the board.": "هذا الرابط للعرض فقط: يمكنك رؤية اللوحة، لكن نتائجك تبقى على هذا الجهاز. اطلب من المالك دعوتك بالبريد الإلكتروني لتنضم إلى اللوحة.",
"This week: {0} — {1}. Top 3 at the end of the week win 500 / 300 / 200 CR.": "هذا الأسبوع: {0} — {1}. الثلاثة الأوائل في نهاية الأسبوع يربحون 500 / 300 / 200 CR.",
