"Rammed by a {0}": "صدمك {0}",
"Brutes block from the front: bounce off a rail first or hit them from behind.": "المتوحشون يصدون من الأمام: ارتد عن السياج أولاً أو اضربهم من الخلف.",
"Phantoms shimmer before they lunge: dash away or strike first.": "الأشباح تومض قبل أن تنقض: اندفع بعيداً أو اضرب أولاً.",
"Slash enemies before they reach you, or dodge sideways.": "اضرب الأعداء قبل أن يصلوا إليك، أو راوغ جانباً.",
"Shot by a SNIPER": "أصابك قناص",
"Snipers aim with an orange laser first: step off the line or parry the shot.": "القناصة يصوبون بليزر برتقالي أولاً: ابتعد عن الخط أو اصدّ الطلقة.",
"Shot by a roof turret": "أصابك برج على السطح",
"Dash through a turret to hack it. It fights for you after that.": "اندفع عبر البرج لتخترقه. سيقاتل معك بعد ذلك.",
"Shot by a firewall node": "أصابتك عقدة جدار الحماية",
"Destroy the nodes quickly, and keep moving between them.": "دمّر العقد بسرعة، وواصل التنقل بينها.",
"Shot by {0}": "أصابك {0}",
"Watch the boss pattern, slash bullets back, and only commit when it is open.": "راقب نمط الزعيم، وأعد الرصاص بالضرب، ولا تهاجم إلا عندما ينكشف.",
"Shot by a {0}": "أصابك {0}",
"Slash bullets as your dash starts for a perfect parry; near misses charge Overdrive.": "اضرب الرصاص لحظة بدء اندفاعك لصدّ مثالي؛ المراوغات القريبة تشحن الأوفردرايف.",
"Caught in a bomber blast": "علقت في انفجار مفجّر",
"Bombers blink before they explode. Slash them early or step out of the ring.": "المفجّرون يومضون قبل أن ينفجروا. اضربهم مبكراً أو اخرج من الحلقة.",
"Hit by an EMP strike": "أصابتك ضربة كهرومغناطيسية",
"Blue circles mark the strikes. Step out before they land.": "الدوائر الزرقاء تحدد الضربات. اخرج منها قبل أن تسقط.",
"Caught in a VOLATILE explosion": "علقت في انفجار متفجر",
"VOLATILE elites explode after they die. Dash away from the orange ring.": "نخبة المتفجرين تنفجر بعد موتها. اندفع بعيداً عن الحلقة البرتقالية.",
"Burned by a laser beam": "أحرقك شعاع ليزر",
"Beams show a dashed line first. Move aside, or dash straight through.": "الأشعة تُظهر خطاً متقطعاً أولاً. تنحَّ جانباً، أو اندفع عبرها مباشرة.",
"Crushed by the Warden stomp": "سحقتك دوسة الحارس",
"The red circle shows where it lands. Leave the circle.": "الدائرة الحمراء تُظهر أين سيهبط. اخرج من الدائرة.",
"Cut down by Kage's dash": "أسقطك اندفاع كاغي",
"Dash INTO his red line to clash and stun him.": "اندفع نحو خطه الأحمر لتصطدم به وتصعقه.",
"Hit by the express train": "صدمك القطار السريع",
"Red stripes mean a train is coming down that track.": "الخطوط الحمراء تعني أن قطاراً قادم على تلك السكة.",
"Rammed by {0}": "صدمك {0}",
"THE BOSS": "الزعيم",
"Do not stand next to the boss; strike and bounce away.": "لا تقف بجوار الزعيم؛ اضرب وارتد بعيداً.",
"Fried by Raijin's lightning curtain": "أحرقك ستار برق رايجين",
"Go through the green gap, or dash straight through the wall.": "مرّ عبر الفجوة الخضراء، أو اندفع عبر الجدار مباشرة.",
"Struck by Raijin's lightning": "ضربك برق رايجين",
"Each drum marks a blue circle on you. Keep moving, and break the drums.": "كل طبل يضع دائرة زرقاء عليك. واصل الحركة، واكسر الطبول.",
"Show every tip again": "أظهر كل النصائح مجدداً",
"RESET": "إعادة ضبط",
"DONE": "تم",
"Assist runs still count for the story, but not for leaderboards or ghosts.": "جولات المساعدة تُحتسب للقصة، لكن ليس للوحات الصدارة أو الأشباح.",
"Stats are only where players fail or quit, so the game can be balanced. No names, no messages.": "الإحصاءات تُجمع فقط حيث يفشل اللاعبون أو ينسحبون، لموازنة اللعبة. بلا أسماء ولا رسائل.",
"VERSION {0}": "الإصدار {0}",
"MUSIC DURING RUNS": "الموسيقى أثناء الجولات",
"AUTO: every area and boss has its own track.": "تلقائي: لكل منطقة وزعيم مقطوعته الخاصة.",
"SHUFFLE: a random track every run. Bosses keep their themes.": "عشوائي: مقطوعة عشوائية كل جولة. الزعماء يحتفظون بمقطوعاتهم.",
"Every run plays {0}, bosses included.": "كل جولة تشغّل {0}، بما في ذلك الزعماء.",
