"ON": "تشغيل",
"OFF (guest)": "إيقاف (ضيف)",
"Below 50 FPS the game lowers effects by itself. For testing on friends' phones, turn on Show FPS.": "تحت 50 إطاراً في الثانية تخفّض اللعبة التأثيرات تلقائياً. للاختبار على هواتف الأصدقاء، فعّل إظهار FPS.",
