"That code is not a valid save.": "هذا الرمز ليس حفظاً صالحاً.",
"Attached: version {0}, {1}, screen {2}×{3}, {4} FPS": "مرفق: الإصدار {0}، {1}، الشاشة {2}×{3}، {4} FPS",
"Write a few words first.": "اكتب بضع كلمات أولاً.",
