"MINI-BOSS: {0}": "زعيم صغير: {0}",
"MEDIC DRONE": "درون المسعف",
"Its green beam heals an enemy and gives it a shield. Cut the medic first.": "شعاعه الأخضر يعالج عدواً ويمنحه درعاً. اقطع المسعف أولاً.",
"It copies your last dash a moment later. The pink line shows where it will go: step off it.": "يقلّد اندفاعك الأخير بعد لحظة. الخط الوردي يُظهر وجهته: ابتعد عنه.",
"Dashing into the bright arc bounces you away. Hit the dark side, or use the bounce for a ricochet crit.": "الاندفاع نحو القوس اللامع يرتد بك بعيداً. اضرب الجانب المظلم، أو استخدم الارتداد لضربة حرجة مرتدة.",
"PROXIMITY MINE": "لغم الاقتراب",
"Walking near it sets it off. Dash straight through it to disarm it for points.": "الاقتراب منه يفجّره. اندفع عبره مباشرة لتعطيله وتحصل على نقاط.",
"MINI-BOSS": "زعيم صغير",
"A tough enemy with its own attacks and a health bar. Learn its warning sign, then strike.": "عدو قوي بهجمات خاصة وشريط صحة. تعلّم علامة تحذيره، ثم اضرب.",
"Mini-boss on the roof! Learn its pattern.": "زعيم صغير على السطح! تعلّم نمطه.",
"Big one incoming. Wait for the opening.": "واحد كبير قادم. انتظر الفرصة.",
"Mini-boss down! Great work.": "سقط الزعيم الصغير! عمل رائع.",
"That one hit hard. Nice.": "ذاك ضرب بقوة. أحسنت.",
"The mimic repeats your dash along the pink line. Step off the line after you dash.": "المقلّد يكرر اندفاعك على الخط الوردي. ابتعد عن الخط بعد اندفاعك.",
"The red line is its charge. Step aside and let it hit the wall: that stuns it and drops its shield.": "الخط الأحمر هو اندفاعه. تنحَّ جانباً ودعه يصطدم بالجدار: هذا يصعقه ويُسقط درعه.",
"The wraith fades before it blinks next to you. Keep moving when it fades.": "الطيف يتلاشى قبل أن يظهر بجانبك. واصل الحركة عندما يتلاشى.",
"Blown up by a mine": "فجّرك لغم",
"Do not walk near mines. Dash straight through a mine to disarm it.": "لا تمشِ قرب الألغام. اندفع عبر اللغم مباشرة لتعطيله.",
"Shot by the {0}": "أصابك {0}",
"Mini-bosses fire in patterns. Find the gap in the pattern, and slash the slow shots back.": "الزعماء الصغار يطلقون النار بأنماط. جد الفجوة في النمط، وأعد الطلقات البطيئة بالضرب.",
"SHADOW KUNAI": "كوناي الظل",
"Every dash also throws 3 kunai in a fan.": "كل اندفاع يرمي أيضاً 3 كوناي على شكل مروحة.",
"CHAIN WHIP": "السوط المتسلسل",
"When a dash ends, the chain cracks a wide arc in front of you.": "عند انتهاء الاندفاع، تضرب السلسلة قوساً واسعاً أمامك.",
"PLASMA SPEAR": "رمح البلازما",
"Fast and long. Pierces shields, bubbles and mirrors, and never bounces back.": "سريع وطويل. يخترق الدروع والفقاعات والمرايا، ولا يرتد أبداً.",
"TITAN GAUNTLETS": "قفازات التيتان",
"Short, heavy punches that launch enemies into walls and each other.": "لكمات قصيرة وثقيلة تقذف الأعداء نحو الجدران وبعضهم البعض.",
"SHADOW RAIN": "مطر الظل",
"Every 4th dash throws 6 kunai instead of 3": "كل اندفاع رابع يرمي 6 كوناي بدلاً من 3",
"SNAP": "الفرقعة",
"Critical cracks stun enemies for a second": "الضربات الحرجة بالسوط تصعق الأعداء لثانية",
"LANCE": "الرمح",
"Every enemy you pierce makes the dash longer": "كل عدو تخترقه يطيل الاندفاع",
"ONE-TWO": "واحد-اثنان",
"Every 3rd punch in a row hits three times as hard": "كل لكمة ثالثة متتالية تضرب بثلاثة أضعاف القوة",
"SNAP!": "فرقعة!",
"ONE-TWO!": "واحد-اثنان!",
