"MIND STORM": "عاصفة العقول",
"Hijacks 4 enemies instead of 2, and their final blasts are bigger.": "يختطف 4 أعداء بدلاً من 2، وانفجاراتهم الأخيرة أكبر.",
"LASER CAGE": "قفص الليزر",
