"VERIFY re-runs the saved replay and checks it lands on the same score. Removed scores are set to 0; banned players are hidden from every board.": "التحقق يعيد تشغيل الإعادة المحفوظة ويتأكد أنها تصل إلى النتيجة نفسها. النتائج المحذوفة تُصفَّر؛ واللاعبون المحظورون مخفيون من كل اللوحات.",
