"Defeat Raijin": "اهزم رايجين",
"SEASON": "الموسم",
"Reach tier 10 of a season": "بلغ المستوى 10 في موسم",
"VOID": "الفراغ",
"Fast little skitter-bot that rams you. Cheap, but they come in swarms. Slash them before they touch you.": "روبوت صغير سريع يندفع ليصدمك. رخيص، لكنه يأتي أسراباً. اضربه قبل أن يلمسك.",
"Keeps its distance and aims with an orange laser before it fires. Step off the line, or parry the shot back.": "يحافظ على مسافته ويصوّب بليزر برتقالي قبل أن يطلق. ابتعد عن الخط، أو أعد الطلقة بالصد.",
"A green shield blocks hits from the front. Bounce off a rail first, hit it from behind, or break it with a perfect parry.": "درع أخضر يصد الضربات من الأمام. ارتد عن السياج أولاً، أو اضربه من الخلف، أو اكسره بصدّ مثالي.",
"Rushes you and blinks before it explodes. Slash it early or get out of the ring.": "يندفع نحوك ويومض قبل أن ينفجر. اضربه مبكراً أو اخرج من الحلقة.",
"Circles you and spins out rings of bullets. Dash through the gaps and parry what you can.": "يدور حولك ويطلق حلقات من الرصاص. اندفع عبر الفجوات واصدّ ما تستطيع.",
"Fades out and reappears right next to you. Watch for the shimmer and strike first.": "يتلاشى ويظهر مجدداً بجانبك مباشرة. راقب الوميض واضرب أولاً.",
"Splits into two minis when it dies. Save a dash for the pieces.": "ينقسم إلى صغيرين عند موته. احتفظ باندفاع للقطع.",
"The small half of a splitter. Weak, but quick.": "النصف الصغير من المنقسم. ضعيف لكنه سريع.",
"Tethers its friends to give them shield bubbles. Cut the warden first and the bubbles fall.": "يربط رفاقه ليمنحهم فقاعات درع. اقطع الحارس أولاً فتسقط الفقاعات.",
"Heals the most hurt enemy nearby and gives it a shield. Always cut the medic first.": "يعالج أكثر الأعداء إصابة بالقرب منه ويمنحه درعاً. اقطع المسعف أولاً دائماً.",
"Copies your last dash a moment later. The pink line shows where it will go: step off it.": "يقلّد اندفاعك الأخير بعد لحظة. الخط الوردي يُظهر وجهته: ابتعد عنه.",
"Circles at mid range and drops proximity mines. Dash straight through a mine to disarm it.": "يدور على مسافة متوسطة ويُسقط ألغام اقتراب. اندفع عبر اللغم مباشرة لتعطيله.",
"Its bright arc bounces your dash away. Hit the dark side, or use the bounce for a ricochet crit.": "قوسه اللامع يرد اندفاعك. اضرب الجانب المظلم، أو استخدم الارتداد لضربة حرجة مرتدة.",
"Carries stolen data and blinks to a far corner every time you hit it. Keep chasing before the timer runs out.": "يحمل بيانات مسروقة ويختفي إلى زاوية بعيدة كلما ضربته. واصل المطاردة قبل نفاد الوقت.",
"A golden drone full of credits that runs away. Catch it before it escapes for a jackpot.": "درون ذهبي مليء بالرصيد يهرب. أمسكه قبل أن يفلت لتربح الجائزة الكبرى.",
"A shadow clone of Kage. It dashes along a red line after a short warning.": "نسخة ظل من كاغي. يندفع على خط أحمر بعد تحذير قصير.",
"Mini-boss. A front shield and a charge along a red line. Step aside and let it hit the wall: that stuns it and drops the shield.": "زعيم صغير. درع أمامي واندفاع على خط أحمر. تنحَّ جانباً ودعه يصطدم بالجدار: هذا يصعقه ويُسقط الدرع.",
"Mini-boss. A slow walking tank that fires fans of bullets and drops mines. Stay close to its flank.": "زعيم صغير. دبابة تمشي ببطء تطلق مراوح من الرصاص وتُسقط الألغام. ابقَ قريباً من جانبها.",
"Mini-boss. Spirals bullets, fades out, then blinks next to you with a ring of shots. Keep moving when it fades.": "زعيم صغير. يطلق رصاصاً حلزونياً، يتلاشى، ثم يظهر بجانبك مع حلقة طلقات. واصل الحركة عندما يتلاشى.",
"A train security mech. Cut its weapon arms, then slash the gold weakpoint arc to stagger it.": "روبوت أمن القطار. اقطع أذرع أسلحته، ثم اضرب قوس نقطة الضعف الذهبي لتترنحه.",
"A three-headed gunship. Destroy the heads to drop its shield, then go for the core.": "سفينة حربية بثلاثة رؤوس. دمّر الرؤوس لتُسقط درعها، ثم اتجه إلى النواة.",
"The shadow ronin. Dash into his red line to clash and stun him, then strike.": "رونين الظل. اندفع نحو خطه الأحمر لتصطدم به وتصعقه، ثم اضرب.",
"The rogue transit AI. Break the firewall nodes, then survive the glitch storm.": "ذكاء النقل المتمرد. اكسر عقد جدار الحماية، ثم انجُ من عاصفة الخلل.",
"The storm god of the orbital ring. Break the thunder drums and find the gap in the lightning curtain.": "إله العاصفة في الحلقة المدارية. اكسر طبول الرعد وجد الفجوة في ستار البرق.",
"Season reward: claim it on the SEASON screen ({0}).": "مكافأة الموسم: استلمها من شاشة الموسم ({0}).",
