"DISBAND CREW": "حلّ الفريق",
"LEAVE CREW": "غادر الفريق",
"TAP AGAIN TO CONFIRM": "انقر مرة أخرى للتأكيد",
"CREW TABLE": "جدول الفرق",
"No crews yet. Start the first one.": "لا توجد فرق بعد. أنشئ الفريق الأول.",
"1 member": "عضو واحد",
"{0} members": "{0} أعضاء",
"REMOVE": "إزالة",
"SURE?": "متأكد؟",
