"DEEP DIVE": "غوص عميق",
"RIPTIDE": "تيار جارف",
"THE BELLS RING TRUE": "الأجراس ترنّ بصدق",
"WRONG BELL": "جرس خاطئ",
"HIT THE LIT BELL: THE NUMBERS SHOW THE ORDER": "اضرب الجرس المضيء: الأرقام تبيّن الترتيب",
"THE BELLS AWAKEN": "الأجراس تستيقظ",
