"COLLECT {0} DATA SHARDS": "اجمع {0} شظايا بيانات",
"ESCORT THE CARGO DRONE FOR {0}s": "رافق درون الشحن لمدة {0} ثانية",
"DESTROY {0} ENEMIES WITH REFLECTED SHOTS": "دمّر {0} أعداء بطلقات مرتدة",
"DEFEAT THE THREE GATE GUARDIANS": "اهزم حراس البوابات الثلاثة",
"REACH A x{0} COMBO": "حقق كومبو x{0}",
"THE CARGO DRONE WAS DESTROYED": "دُمّر درون الشحن",
"Chapter 7 is open: NEON TIDE.": "الفصل 7 مفتوح: مدّ النيون.",
"TIDE DRAGON hero unlocked in the Arsenal.": "البطل تنين المدّ متاح الآن في الترسانة.",
"IRON MONK hero unlocked in the Arsenal.": "البطل الراهب الحديدي متاح الآن في الترسانة.",
"PRIME FRAME hero unlocked in the Arsenal. ACT II complete!": "البطل هيكل برايم متاح الآن في الترسانة. اكتمل الفصل الثاني من القصة!",
"Crushed by KUROGANE PRIME's stomp": "سحقتك دوسة كوروغانه برايم",
"Crushed by LEVIATHAN": "سحقك ليفياثان",
"Its body hurts to touch. Dash through it, never walk into it, and step off the red lunge line.": "لمس جسده يؤذي. انقضّ عبره ولا تمشِ نحوه أبدًا، وابتعد عن خط الانقضاض الأحمر.",
"Caught by LEVIATHAN breaching": "أصابك ليفياثان عند خروجه",
"When it dives, a circle follows you. Leave the circle before it closes.": "عندما يغوص تتبعك دائرة. اخرج منها قبل أن تنغلق.",
"Cut by BENKEI's sweep": "قطعتك ضربة بنكي الدائرية",
"The red sector shows the cut. Step out of it, or dash through as it swings.": "القطاع الأحمر يبيّن الضربة. اخرج منه أو انقضّ عبره أثناء الدوران.",
"Cut by the blade rain": "قطعك مطر النصال",
"Red lines strike a moment later. Stand between them.": "الخطوط الحمراء تضرب بعد لحظة. قف بينها.",
"Struck by KUROGANE PRIME's lightning": "أصابك برق كوروغانه برايم",
"A blue circle follows you during ZERO HOUR. Keep moving.": "في ساعة الصفر تتبعك دائرة زرقاء. استمر في الحركة.",
