"Defeat LEVIATHAN": "اهزم ليفياثان",
"BELL RINGER": "قارع الأجراس",
"Defeat BENKEI.SYS": "اهزم BENKEI.SYS",
"Defeat KUROGANE PRIME": "اهزم كوروغانه برايم",
