"The enemy that breaks your shields remembers you. It gets a name and comes back in later runs, stronger every time it wins. Slay it for a big bounty.": "العدو الذي يحطّم دروعك يتذكرك. يحصل على اسم ويعود في جولات لاحقة، أقوى في كل مرة يفوز فيها. اهزمه لتحصل على مكافأة كبيرة.",
"Your own loft: a rack with every blade you own, a trophy statue for every boss you beat, an arcade cabinet, a WANTED poster for your nemesis, and your pet wandering around.": "شقتك الخاصة: رف عليه كل نصل تملكه، وتمثال جائزة لكل زعيم هزمته، وآلة أركيد، وملصق \"مطلوب\" لعدوك اللدود، وحيوانك يتجول في المكان.",
"Place up to six waves of enemies, pick a theme, props and a final boss, test it and share it as a code. Two creator picks to start with.": "ضع حتى ست موجات من الأعداء، واختر سمة وعناصر وزعيمًا أخيرًا، جرّبها وشاركها كرمز. مع مرحلتين من اختيار المطوّر للبداية.",
"CLIPS TO SHARE": "مقاطع للمشاركة",
"Pick the moment (boss kill, nemesis, SSS rank or the finale) and the length. Your name and score go on the clip, and you can share it straight from the phone.": "اختر اللحظة (هزيمة زعيم، العدو اللدود، رتبة SSS أو الختام) والطول. يظهر اسمك ونقاطك على المقطع، ويمكنك مشاركته مباشرة من الهاتف.",
"Every weapon swing has its own sound and its own vibration, and real swing animations for every weapon.": "لكل ضربة سلاح صوتها واهتزازها الخاص، مع رسوم ضربات حقيقية لكل سلاح.",
