"A featured climb every week: Twin Curses, Glass Tower, Boss Ascent or Relic Storm. Turn it on at the Tower Altar.": "تسلّق مميز كل أسبوع: لعنات مزدوجة، برج الزجاج، صعود الزعماء أو عاصفة الآثار. فعّله من مذبح البرج.",
