"Enemies breathe, wind up before they attack (watch the closing red ring), flinch away from every hit and break apart their own way when they die.": "الأعداء يتنفسون، ويتهيؤون قبل الهجوم (راقب الحلقة الحمراء التي تنغلق)، ويرتدّون من كل ضربة، ويتحطم كل منهم بطريقته عند موته.",
"Event climb: {0}. Event climbs are not ranked.": "تسلّق حدث: {0}. تسلّقات الأحداث غير مصنّفة.",
"Event climbs are not ranked.": "تسلّقات الأحداث غير مصنّفة.",
"Every floor starts with 3s of invulnerability, and lifts you off your last shield": "يبدأ كل طابق بـ3 ث من المناعة، ويرفعك عن درعك الأخير",
"FRIEND CHALLENGE": "تحدي صديق",
"Four new relics (Storm Blade, Lucky Clover, Guardian Halo, Blood Pact), two new curses (Minefield, Heavy Blade) and three tower heroes to unlock.": "أربعة آثار جديدة (نصل العاصفة، برسيم الحظ، هالة الحارس، عهد الدم)، ولعنتان جديدتان (حقل ألغام، نصل ثقيل)، وثلاثة أبطال برج لفتحهم.",
"GLASS TOWER": "برج الزجاج",
"GUARDIAN HALO": "هالة الحارس",
"Gold wings from the top of the Neon Tower. Clear floor 5 to claim it.": "أجنحة ذهبية من قمة برج النيون. طهّر الطابق 5 لتحصل عليه.",
"HEAVY BLADE": "نصل ثقيل",
"LUCKY CLOVER": "برسيم الحظ",
"MORE TOWER": "المزيد من البرج",
"Mines keep appearing on the roof": "تستمر الألغام بالظهور على السطح",
"New bounties for the Tower, custom levels and the highway, a REPORT A PROBLEM button on the title screen, and saves that merge custom levels and soul shards correctly across devices.": "مهام جديدة للبرج والمراحل المخصصة والطريق السريع، وزر \"الإبلاغ عن مشكلة\" في شاشة البداية، وحفظ يدمج المراحل المخصصة وشظايا الروح بشكل صحيح بين الأجهزة.",
"One shield for the whole climb, but a relic every third floor.": "درع واحد للتسلّق كله، لكن أثر كل ثالث طابق.",
"Paste a challenge code (ODC1.…)": "الصق رمز تحدٍّ (ODC1.…)",
"Play the same roof your friend played, with the same seed, and try to beat their score.": "العب على السطح نفسه الذي لعبه صديقك، بالبذرة نفسها، وحاول التفوق على نتيجته.",
"RELIC STORM": "عاصفة الآثار",
"Reach floor {n} of the Neon Tower": "اصل إلى الطابق {n} في برج النيون",
"Ride {n} m in Highway Chase": "اقطع {n} م في مطاردة الطريق السريع",
"SHARE & CHALLENGE now adds a code. Your friend pastes it in Arcade and plays the very same roof, same seed, and the result says who won.": "زر \"شارك وتحدَّ\" يضيف الآن رمزًا. يلصقه صديقك في الأركيد ويلعب على السطح نفسه بالبذرة نفسها، وتُظهر النتيجة من فاز.",
"STORM BLADE": "نصل العاصفة",
"Same roof, same seed: paste this code in Arcade → Friend challenge: {0}": "السطح نفسه والبذرة نفسها: الصق هذا الرمز في الأركيد ← تحدي صديق: {0}",
"Start with two relics. Enemies have 25% more health.": "ابدأ بأثرين. للأعداء صحة أكثر بـ25%.",
"TOWER WEEKLY EVENT": "حدث البرج الأسبوعي",
"TWIN CURSES": "لعنات مزدوجة",
"Two curses on every floor. x2 soul shards.": "لعنتان في كل طابق. شظايا روح ×2.",
"WEEKLY EVENT": "حدث أسبوعي",
"Wears every curse the tower threw at it. Clear floor 10 to claim it.": "يحمل كل لعنة رماها عليه البرج. طهّر الطابق 10 لتحصل عليه.",
"You beat {0}! {1} vs {2}.": "تفوقت على {0}! {1} مقابل {2}.",
"{0} scored {1}. {2} more to beat it.": "سجّل {0} {1}. تحتاج {2} أخرى لتتفوق.",
"SHINIGAMI": "شينيغامي",
"Death god. One shield, relentless enemies, and it only gets harder while you play well.": "إله الموت. درع واحد، أعداء لا يرحمون، ويزداد الأمر صعوبة كلما لعبت جيدًا.",
"The intended challenge. The better you play, the harder it pushes back.": "التحدي المقصود. كلما لعبت أفضل، ازداد الضغط عليك.",
"HARDER": "أصعب",
"Every difficulty above ROOKIE is tougher: enemies have more health, move and shoot faster, come in bigger waves, and bosses hit harder. The game also watches how well you play and keeps pushing back while you are on a roll.": "كل مستوى صعوبة فوق المبتدئ أصعب: للأعداء صحة أكبر، ويتحركون ويطلقون أسرع، ويأتون في موجات أكبر، والزعماء يضربون أقوى. واللعبة تراقب أداءك وتواصل الضغط ما دمت في أوج تألقك.",
"A fifth difficulty for the best: one shield, relentless enemies and x4 score.": "مستوى صعوبة خامس للأفضل: درع واحد، أعداء لا يرحمون، ونقاط ×4.",
"STORM NODACHI": "نوداتشي العاصفة",
"A huge two-handed blade. When a dash ends, it cuts a full circle around you.": "نصل ضخم بيدين. عند انتهاء الاندفاع يقطع دائرة كاملة حولك.",
"NEON CHAKRAM": "شاكرام النيون",
