"STEEL FAN": "المروحة الفولاذية",
"A folding war fan. A wider perfect-parry window, and parried shots split into three.": "مروحة حرب قابلة للطي. نافذة صد مثالي أوسع، والطلقات المصدودة تنقسم إلى ثلاث.",
"The circle cut strikes twice": "ضربة الدائرة تضرب مرتين",
"ORBIT": "المدار",
"The ring flies a second loop before it comes home": "تطير الحلقة دورة ثانية قبل أن تعود",
"GALE": "العصف",
"GALE!": "عصف!",
"Perfect parries blow nearby enemies away and stun them": "الصد المثالي يقذف الأعداء القريبين ويصعقهم",
"SPIRIT FOX": "ثعلب الروح",
"Three-tailed spirit": "روح بثلاثة ذيول",
"A three-tailed fox spirit of pale fire. Every 30 seconds it mends one of your shields.": "روح ثعلب بثلاثة ذيول من نار شاحبة. كل 30 ثانية يصلح أحد دروعك.",
"NIGHT OWL": "بومة الليل",
"Scout owl": "بومة استطلاع",
"A silent scout with lamp eyes. Every 8 seconds it marks the toughest enemy near you: marked enemies take 50% more damage.": "كشّاف صامت بعينين كالمصباح. كل 8 ثوانٍ يعلّم أقوى عدو قربك: الأعداء المعلَّمون يتلقون ضررًا أكبر بـ50%.",
"SHELL BOT": "روبوت الصدفة",
"Mech turtle": "سلحفاة آلية",
"A little armored mech turtle. Every 10 seconds it charges a shell that blocks the next bullet that would hit you.": "سلحفاة آلية صغيرة مدرعة. كل 10 ثوانٍ تشحن صدفة تصد الرصاصة التالية التي كانت ستصيبك.",
"Mends a shield every {0}s": "يصلح درعًا كل {0} ث",
"Every {0}s · marked enemies take +{1}% damage": "كل {0} ث · الأعداء المعلَّمون يتلقون +{1}% ضرر",
