"Holds two shells · a new one every {0}s": "يحمل صدفتين · واحدة جديدة كل {0} ث",
"Play live with friends anywhere, no account needed. One phone hosts and sends an invite code; each friend sends back a reply code.": "العب مباشرة مع أصدقائك من أي مكان دون حساب. هاتف واحد يستضيف ويرسل رمز دعوة، وكل صديق يرد برمز رد.",
