"1. SEND THIS INVITE": "1. أرسل هذه الدعوة",
"2. PASTE YOUR FRIEND'S REPLY": "2. الصق رد صديقك",
"1. PASTE THE HOST'S INVITE": "1. الصق دعوة المضيف",
"2. SEND THIS REPLY TO THE HOST": "2. أرسل هذا الرد إلى المضيف",
