"Paste the invite code here": "الصق رمز الدعوة هنا",
"Connection code": "رمز الاتصال",
"CONNECT": "اتصل",
"MAKE MY REPLY": "أنشئ ردّي",
"You join the room as soon as the host pastes it.": "ستنضم إلى الغرفة فور أن يلصقه المضيف.",
"CANCEL": "إلغاء",
"INVITE ANOTHER FRIEND": "ادعُ صديقًا آخر",
