"That is not an invite code.": "هذا ليس رمز دعوة.",
"Make an invite first.": "أنشئ دعوة أولًا.",
"That reply belongs to another invite. Send a new invite.": "هذا الرد يخص دعوة أخرى. أرسل دعوة جديدة.",
"Could not connect. Try again, or both join the same Wi-Fi.": "تعذر الاتصال. حاول مجددًا، أو اتصلا بشبكة Wi-Fi نفسها.",
"This copy of the game runs without claude.ai, so live play connects phones directly.": "هذه النسخة من اللعبة تعمل دون claude.ai، لذا يربط اللعب المباشر الهواتف مباشرة.",
"Live rooms on claude.ai need the shared link, signed in. You can also connect directly:": "غرف claude.ai المباشرة تحتاج إلى الرابط المشترك وتسجيل الدخول. يمكنك أيضًا الاتصال مباشرة:",
