"EVERY CABLE IS A COIL. EVERY COIL IS A GRAVE.": "كل كابل لفّة. وكل لفّة قبر.",
"Its tail broke off and it is hunting you too! Watch both of them!": "انفصل ذيله وصار يطاردك أيضًا! راقب الاثنين!",
"Crushed by ORYU.EXE": "سحقك ORYU.EXE",
"Never touch its body outside a dash, and get out of the ring before it closes.": "لا تلمس جسده خارج الاندفاع، واخرج من الحلقة قبل أن تنغلق.",
"The serpent throws a ring around you. Dash out before it snaps shut, and never touch its body outside a dash.": "يرمي الثعبان حلقة حولك. اندفع خارجها قبل أن تنغلق، ولا تلمس جسده خارج الاندفاع.",
