"GRIP": "القبضة",
"Dash charges recharge 4% faster per level · level 5: +1 dash charge": "شحنات الاندفاع تعاد أسرع بـ 4% لكل مستوى · المستوى 5: +1 شحنة اندفاع",
"CORE": "النواة",
"Critical hits 8% harder per level · level 5: wider perfect-parry window": "الضربات الحرجة أقوى بـ 8% لكل مستوى · المستوى 5: نافذة صدّ مثالي أوسع",
"WEAPON TREE": "شجرة السلاح",
"SECOND WEAPON: ON (TAP TO REMOVE)": "السلاح الثاني: مفعّل (اضغط للإزالة)",
"THIS IS YOUR MAIN WEAPON": "هذا سلاحك الرئيسي",
"SET AS SECOND WEAPON": "اجعله السلاح الثاني",
"SWAP BLADES IN A RUN WITH THE SWAP BUTTON OR F": "بدّل النصال أثناء الجولة بزر SWAP أو F",
