"BACK TO TITLE": "العودة إلى الشاشة الرئيسية",
"DAILY OP already completed today. A new one starts tomorrow.": "أُنجزت المهمة اليومية اليوم بالفعل. تبدأ مهمة جديدة غدًا.",
