"+20% reach": "+20% مدى",
"SHADOW REFUND": "استرداد الظل",
"Every 4th kill refunds a dash charge": "كل قتل رابع يعيد شحنة اندفاع",
"SPIRIT ORBS": "كرات الروح",
"Every 5th kill throws 2 spirit orbs": "كل قتل خامس يطلق كرتي روح",
"WARD": "حماية",
"ORB STORM": "عاصفة الكرات",
"Spirit orbs come in threes": "كرات الروح تأتي ثلاثًا",
"OVERFLOW": "فيض",
"Overdrive charges 30% faster": "الأوفردرايف يُشحن أسرع بـ30%",
"SHORT": "قصير",
"MID": "متوسط",
"LONG": "طويل",
"FORGED BLADE": "نصل مصهور",
"HERO FORGE": "مصهر الأبطال",
